static void amdgpu_job_timedout ( struct amd_sched_job * s_job ) { struct amdgpu_job * job = container_of ( s_job , amdgpu_job , base ) ; DRM_ERROR ( "ring %s timeout, last signaled seq=%u, last emitted seq=%u\n" , job -> base . sched -> name , atomic_read ( & job -> ring -> fence_drv . last_seq ) , job -> ring -> fence_drv . sync_seq ) ; amdgpu_gpu_reset ( job -> adev , NULL ) ; } 